macro_rules! twice {
    ($x:expr) => {
        $x + $x
    };
}

fn main() {
    println!("{}", twice!(5));
}

macro_rules! square {
    ($x:expr) => {
        $x * $x
    };
}

fn main() {
    println!("{}", square!(1 + 2));
}

macro_rules! show {
    ($x:___) => {
        println!("{}", $x)
    };
}

fn main() {
    show!(2 + 3);
}

macro_rules! make_fn {
    ($name:ident, $v:expr) => {
        fn $name() -> i32 {
            $v
        }
    };
}

make_fn!(seven, 3 + 4);

fn main() {
    println!("{}", seven());
}

