macro_rules! sum {
    () => { 0 };
    ($x:expr $(, $rest:expr)*) => {
        $x + sum!($($rest),*)
    };
}

fn main() {
    println!("{} {} {}", sum!(), sum!(5), sum!(1, 2, 3));
}
